// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api-tokens", wrapper.ListApiTokens)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api-tokens", wrapper.CreateApiToken)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api-tokens/{id}", wrapper.DeleteApiToken)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/articles", wrapper.ListArticles)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/articles/{id}", wrapper.GetArticle)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/articles/{id}/publish", wrapper.PublishArticle)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/articles/{id}/rating", wrapper.RateArticle)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/login", wrapper.Login)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/clients", wrapper.ListClientSegments)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/clients/{id}/segment", wrapper.SetClientSegmentOverride)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/emailscrape", wrapper.ScrapeEmails)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/emailscrape/jobs/{id}", wrapper.GetScrapeJob)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/emailscrape/jobs/{id}/cancel", wrapper.CancelScrapeJob)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/generate", wrapper.GenerateArticle)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/generate/batch", wrapper.GenerateBatch)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/healthz", wrapper.GetHealthz)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/leads/stats", wrapper.GetLeadStats)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/linkbuilding/place-backlinks", wrapper.PlaceBacklinks)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/linkbuilding/placements", wrapper.ListPlacements)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/linkbuilding/placements/history", wrapper.ListPlacementHistory)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/linkbuilding/placements/{run_id}/cancel", wrapper.CancelPlacement)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/users", wrapper.ListUsers)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/wordpress-sites", wrapper.ListWordpressSites)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/wordpress-sites", wrapper.CreateWordpressSite)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/wordpress-sites/{id}", wrapper.DeleteWordpressSite)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/wordpress-sites/{id}", wrapper.GetWordpressSite)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/wordpress-sites/{id}", wrapper.UpdateWordpressSite)
	})

	return r
}

